template <class BidirectionalIterator>
BidirectionalIterator std::prev(BidirectionalIterator x,
    typename std::iterator_traits<BidirectionalIterator>::difference_type n = 1);

// Implementation notes: The compiler instantiates this template at compile-time. For example, if BidirectionalIterator is a pointer (e.g., int*), the function might expand to: return x - n; For non-random access iterators, it loops: while (n-- > 0) { --x; } ensuring bidirectional traversal.
